INSERT INTO public.intranet_modules(page_id,definition) VALUES('finance.fiscal',$module${"id":"finance.fiscal","path":"/pole/finance/fiscal","label":"Fiscalité & flux","scope":"finance","transversal":true,"restrictedRoles":["ceo","coo","cto","cfo","comptable","controleur_gestion","analyste_financier","tresorier","gestionnaire_facturation","gestionnaire_remboursements","gestionnaire_paiements","responsable_fournisseurs","gestionnaire_fournisseurs","conformite_fournisseurs","acheteur","directeur_marketplace","responsable_marketplace","gestionnaire_boutiques","gestionnaire_vendeurs","gestionnaire_commandes","gestionnaire_litiges","responsable_logistique","gestionnaire_transport","gestionnaire_entrepots","gestionnaire_stocks","coordinateur_expeditions","responsable_support","gestionnaire_tickets","juriste","conformite_juridique","responsable_conformite","gestionnaire_contrats","responsable_tech","dev_backend","dev_fullstack","devops_engineer","sre","dba","rssi","analyste_rgpd","responsable_qualite","auditeur_qualite"],"public":false,"approvalLevels":2,"fields":[],"description":"Pilotage fiscal et réglementaire par flux et par pôle ; risques, pièces, obligations et première déclaration.","recordLabel":"Fiche de pilotage fiscal"}$module$::jsonb)ON CONFLICT(page_id)DO UPDATE SET definition=EXCLUDED.definition;

-- Fiscal reference and operational tracking only. No tax filing, invoice issue or payment.
CREATE TABLE public.bib_fiscal_reference_catalog (
 record_id text PRIMARY KEY,
 body jsonb NOT NULL CHECK(jsonb_typeof(body)='object'),
 reference_version text NOT NULL DEFAULT '2026-11-06'
);
CREATE TABLE public.bib_fiscal_records (
 record_id text NOT NULL,
 test_account boolean NOT NULL,
 body jsonb NOT NULL CHECK(jsonb_typeof(body)='object'),
 revision bigint NOT NULL DEFAULT 1 CHECK(revision>0),
 created_by uuid NOT NULL REFERENCES public.profiles(id),
 updated_by uuid NOT NULL REFERENCES public.profiles(id),
 updated_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(record_id,test_account)
);
CREATE TABLE public.bib_fiscal_events (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 record_id text NOT NULL,
 test_account boolean NOT NULL,
 actor_id uuid NOT NULL REFERENCES public.profiles(id),
 action text NOT NULL,
 before_body jsonb,
 after_body jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX bib_fiscal_events_record_idx ON public.bib_fiscal_events(record_id,test_account,created_at DESC);
ALTER TABLE public.bib_fiscal_reference_catalog ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.bib_fiscal_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.bib_fiscal_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.bib_fiscal_reference_catalog,public.bib_fiscal_records,public.bib_fiscal_events FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.bib_fiscal_reference_catalog,public.bib_fiscal_records,public.bib_fiscal_events TO authenticated;
CREATE POLICY bib_fiscal_catalog_read ON public.bib_fiscal_reference_catalog FOR SELECT TO authenticated USING(public.can_intranet_action('finance.fiscal','read'));
CREATE POLICY bib_fiscal_records_read ON public.bib_fiscal_records FOR SELECT TO authenticated USING(public.can_intranet_action('finance.fiscal','read')AND test_account=public.intranet_is_test_mode());
CREATE POLICY bib_fiscal_events_read ON public.bib_fiscal_events FOR SELECT TO authenticated USING(public.can_intranet_action('finance.fiscal','read')AND test_account=public.intranet_is_test_mode());

CREATE FUNCTION public.bib_fiscal_body(p_id text,p_test boolean,p_replacement jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT CASE WHEN p_replacement->>'id'=p_id THEN p_replacement ELSE
  (SELECT coalesce(r.body,c.body) FROM (SELECT * FROM public.bib_fiscal_records WHERE test_account=p_test)r
   FULL JOIN public.bib_fiscal_reference_catalog c USING(record_id) WHERE coalesce(r.record_id,c.record_id)=p_id) END;
$$;
REVOKE ALL ON FUNCTION public.bib_fiscal_body(text,boolean,jsonb) FROM PUBLIC,anon,authenticated;

CREATE FUNCTION public.list_bib_fiscal_records()
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE result jsonb;
BEGIN
 IF auth.uid()IS NULL OR NOT coalesce(public.can_intranet_action('finance.fiscal','read'),false)THEN RAISE EXCEPTION 'fiscal_read_forbidden' USING ERRCODE='42501';END IF;
 SELECT coalesce(jsonb_agg(coalesce(r.body,c.body)ORDER BY coalesce(r.record_id,c.record_id)),'[]') INTO result
 FROM (SELECT * FROM public.bib_fiscal_records WHERE test_account=public.intranet_is_test_mode())r FULL JOIN public.bib_fiscal_reference_catalog c USING(record_id);
 RETURN jsonb_build_object('records',result,'canWrite',public.can_intranet_action('finance.fiscal','update')OR public.can_intranet_action('finance.fiscal','create'),'mode','saved');
END; $$;

CREATE FUNCTION public.save_bib_fiscal_record(p_record jsonb,p_expected_revision bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE actor uuid:=auth.uid(); mode boolean:=public.intranet_is_test_mode(); existing public.bib_fiscal_records%ROWTYPE;
 base jsonb; next_body jsonb; record_key text:=p_record->>'id'; dependency text; item jsonb; revision_next bigint; action_name text;
BEGIN
 IF actor IS NULL OR NOT coalesce(public.can_intranet_action('finance.fiscal','read'),false) THEN RAISE EXCEPTION 'fiscal_write_forbidden' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_record)IS DISTINCT FROM 'object' OR octet_length(p_record::text)>200000
  OR record_key IS NULL OR record_key!~'^[A-Z]{2,8}-[A-Z0-9-]{1,80}$'
  OR p_expected_revision IS NULL OR p_expected_revision<0 THEN RAISE EXCEPTION 'invalid_fiscal_record' USING ERRCODE='22023';END IF;
 -- Serialize a record's first overlay creation as well as subsequent revisions.
 PERFORM pg_advisory_xact_lock(hashtextextended(record_key||':'||mode::text,0));
 SELECT * INTO existing FROM public.bib_fiscal_records WHERE record_id=record_key AND test_account=mode FOR UPDATE;
 SELECT body INTO base FROM public.bib_fiscal_reference_catalog WHERE record_id=record_key;
 IF coalesce(existing.revision,0)<>p_expected_revision OR (p_record->>'revision')::bigint<>p_expected_revision THEN RAISE EXCEPTION 'stale_fiscal_revision' USING ERRCODE='40001';END IF;
 IF NOT coalesce(public.can_intranet_action('finance.fiscal',CASE WHEN existing.record_id IS NOT NULL OR base IS NOT NULL THEN 'update' ELSE 'create' END),false)THEN RAISE EXCEPTION 'fiscal_write_forbidden' USING ERRCODE='42501';END IF;
 IF coalesce(length(btrim(p_record->>'title')),0)NOT BETWEEN 3 AND 200
  OR coalesce(p_record->>'kind','')NOT IN('flow','risk','document','obligation')
  OR coalesce(p_record->>'confidence','')NOT IN('Confirmé','À valider','À surveiller')
  OR coalesce(p_record->>'status','')NOT IN('À préparer','En cours','Bloqué','En revue','Validé')
  OR coalesce(p_record->>'risk','')NOT IN('Faible','Modéré','Élevé','Critique')
  OR coalesce(p_record->>'dueType','')NOT IN('Légale','Interne','À déterminer')
  OR coalesce(p_record->>'pole','')NOT IN('Finance','Conformité & Juridique','Fournisseurs & Produits','Opérations & Logistique','Marketplace & Customer','Support & Customer Success','Produit & Engineering','Security & IT','Direction')
  OR jsonb_typeof(p_record->'contributors')IS DISTINCT FROM 'array'
  OR jsonb_typeof(p_record->'dependencies')IS DISTINCT FROM 'array'
  OR jsonb_typeof(p_record->'controls')IS DISTINCT FROM 'array'
  OR jsonb_typeof(p_record->'evidence')IS DISTINCT FROM 'array'
  OR jsonb_typeof(p_record->'details')IS DISTINCT FROM 'object'
  OR jsonb_typeof(p_record->'refs')IS DISTINCT FROM 'array'
  OR jsonb_typeof(p_record->'owner')IS DISTINCT FROM 'string'
  OR jsonb_typeof(p_record->'summary')IS DISTINCT FROM 'string'
  OR jsonb_typeof(p_record->'entity')IS DISTINCT FROM 'string'
  OR jsonb_typeof(p_record->'activity')IS DISTINCT FROM 'string'
  OR jsonb_typeof(p_record->'flow')IS DISTINCT FROM 'string'
  OR jsonb_typeof(p_record->'notes')IS DISTINCT FROM 'string'
  OR jsonb_typeof(p_record->'trigger')IS DISTINCT FROM 'string'
  OR jsonb_array_length(p_record->'evidence')>40 OR jsonb_array_length(p_record->'controls')>30
  OR jsonb_array_length(p_record->'dependencies')>40 OR jsonb_array_length(p_record->'contributors')>12 THEN RAISE EXCEPTION 'invalid_fiscal_fields' USING ERRCODE='22023';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(p_record->'details')d WHERE jsonb_typeof(d.value)IS DISTINCT FROM 'string')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_record->'refs')r WHERE jsonb_typeof(r)IS DISTINCT FROM 'string')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_record->'contributors')p WHERE jsonb_typeof(p)IS DISTINCT FROM 'string')
  OR (p_record?'relatedEntities' AND jsonb_typeof(p_record->'relatedEntities')IS DISTINCT FROM 'array')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(p_record->'relatedEntities','[]'))e WHERE jsonb_typeof(e)IS DISTINCT FROM 'string')
  OR (p_record?'likelihood' AND (jsonb_typeof(p_record->'likelihood')IS DISTINCT FROM 'number' OR (p_record->>'likelihood')::numeric NOT BETWEEN 1 AND 5))
  OR (p_record?'severity' AND (jsonb_typeof(p_record->'severity')IS DISTINCT FROM 'number' OR (p_record->>'severity')::numeric NOT BETWEEN 1 AND 5))
 THEN RAISE EXCEPTION 'invalid_fiscal_value_types' USING ERRCODE='22023';END IF;
 IF base IS NOT NULL AND p_record->>'kind'IS DISTINCT FROM base->>'kind' OR existing.record_id IS NOT NULL AND p_record->>'kind'IS DISTINCT FROM existing.body->>'kind' THEN RAISE EXCEPTION 'immutable_fiscal_kind' USING ERRCODE='22023';END IF;
 IF coalesce(p_record->>'due','')<>''THEN PERFORM (p_record->>'due')::date;END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_record->'controls')LOOP
  IF jsonb_typeof(item)IS DISTINCT FROM 'object' OR coalesce(length(btrim(item->>'label')),0)NOT BETWEEN 1 AND 400 OR jsonb_typeof(item->'done')IS DISTINCT FROM 'boolean'THEN RAISE EXCEPTION 'invalid_fiscal_control' USING ERRCODE='22023';END IF;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(p_record->'evidence')LOOP
  IF jsonb_typeof(item)IS DISTINCT FROM 'object' OR coalesce(length(btrim(item->>'name')),0)NOT BETWEEN 1 AND 240 OR coalesce(item->>'url','')!~'^https://' OR coalesce(item->>'type','')<>'link'THEN RAISE EXCEPTION 'invalid_fiscal_evidence' USING ERRCODE='22023';END IF;
 END LOOP;
 FOR dependency IN SELECT jsonb_array_elements_text(p_record->'dependencies')LOOP
  IF dependency=record_key OR public.bib_fiscal_body(dependency,mode)IS NULL THEN RAISE EXCEPTION 'invalid_fiscal_dependency' USING ERRCODE='22023';END IF;
 END LOOP;
 IF EXISTS(WITH RECURSIVE walk(node,path,cyclic)AS(
  SELECT record_key,ARRAY[record_key],false UNION ALL
  SELECT d.id,w.path||d.id,d.id=ANY(w.path) FROM walk w
   CROSS JOIN LATERAL jsonb_array_elements_text(public.bib_fiscal_body(w.node,mode,p_record)->'dependencies') d(id)
   WHERE NOT w.cyclic AND cardinality(w.path)<100
 )SELECT 1 FROM walk WHERE cyclic)THEN RAISE EXCEPTION 'cyclic_fiscal_dependencies' USING ERRCODE='22023';END IF;
 IF p_record->>'status'='Validé'THEN
  IF NOT coalesce(public.can_intranet_action('finance.fiscal','validate'),false)
   OR existing.record_id IS NULL OR existing.updated_by=actor OR existing.body->>'status'<>'En revue'
   OR (p_record-ARRAY['status','notes','revision'])IS DISTINCT FROM(existing.body-ARRAY['status','notes','revision']) THEN RAISE EXCEPTION 'independent_fiscal_review_required' USING ERRCODE='42501';END IF;
  IF coalesce(length(btrim(p_record->>'owner')),0)=0 OR p_record->>'owner'~*'à affecter|à désigner'
   OR jsonb_array_length(p_record->'evidence')=0 OR jsonb_array_length(p_record->'controls')=0
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_record->'controls')c WHERE (c->>'done')::boolean IS DISTINCT FROM true)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_record->'dependencies')d WHERE public.bib_fiscal_body(d,mode)->>'status'IS DISTINCT FROM 'Validé') THEN RAISE EXCEPTION 'fiscal_validation_incomplete' USING ERRCODE='22023';END IF;
 END IF;
 revision_next:=coalesce(existing.revision,0)+1;next_body:=p_record||jsonb_build_object('revision',revision_next);
 INSERT INTO public.bib_fiscal_records(record_id,test_account,body,revision,created_by,updated_by)
 VALUES(record_key,mode,next_body,revision_next,actor,actor)
 ON CONFLICT(record_id,test_account)DO UPDATE SET body=EXCLUDED.body,revision=EXCLUDED.revision,updated_by=actor,updated_at=now();
 action_name:=CASE WHEN p_record->>'status'='Validé'THEN 'Validation indépendante'WHEN existing.record_id IS NULL THEN 'Fiche enregistrée'ELSE 'Fiche mise à jour'END;
 INSERT INTO public.bib_fiscal_events(record_id,test_account,actor_id,action,before_body,after_body)
 VALUES(record_key,mode,actor,action_name,coalesce(existing.body,base),next_body);
 RETURN next_body;
END; $$;
CREATE FUNCTION public.list_bib_fiscal_events(p_record_id text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE result jsonb;
BEGIN
 IF auth.uid()IS NULL OR NOT coalesce(public.can_intranet_action('finance.fiscal','read'),false)THEN RAISE EXCEPTION 'fiscal_history_forbidden' USING ERRCODE='42501';END IF;
 SELECT coalesce(jsonb_agg(x ORDER BY x.created_at DESC),'[]')INTO result FROM(
  SELECT e.id,e.action,jsonb_build_object('before',e.before_body,'after',e.after_body,'actor',e.actor_id)::text AS body,e.created_at
  FROM public.bib_fiscal_events e WHERE e.record_id=p_record_id AND e.test_account=public.intranet_is_test_mode()ORDER BY e.created_at DESC LIMIT 100)x;
 RETURN result;
END; $$;
REVOKE ALL ON FUNCTION public.list_bib_fiscal_records(),public.save_bib_fiscal_record(jsonb,bigint),public.list_bib_fiscal_events(text)FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.list_bib_fiscal_records(),public.save_bib_fiscal_record(jsonb,bigint),public.list_bib_fiscal_events(text)TO authenticated;

